```typescript
private async persist(payments: Payment[]): Promise<void> {
    const tempPath = `${this.filePath}.${crypto.randomUUID()}.tmp`;
    try {
        await fs.writeFile(tempPath, JSON.stringify(payments, null, 2), 'utf-8');
