import { ConflictError } from '../src/error';

describe('Payment Status Transitions', () => {
    describe('allowedTransitions', () => {
        it('should correctly define allowed state paths', () => {
            expect(allowedTransitions.PENDING).toEqual(['PROCESSING']);
            expect(allowedTransitions.PROCESSING).toEqual(['SUCCESS', 'FAILED']);
            expect(allowedTransitions.SUCCESS).toEqual([]);
            expect(allowedTransitions.FAILED).toEqual([]);
        });
    });

    describe('assertTransition', () => {
        it('should allow valid transition from PENDING to PROCESSING', () => {
            expect(() => assertTransition('PENDING', 'PROCESSING')).not.toThrow();
        });

        it('should allow valid transition from PROCESSING to SUCCESS', () => {
            expect(() => assertTransition('PROCESSING', 'SUCCESS')).not.toThrow();
        });

        it('should allow valid transition from PROCESSING to FAILED', () => {
            expect(() => assertTransition('PROCESSING', 'FAILED')).not.toThrow();
        });

        it('should reject invalid skip from PENDING to SUCCESS', () => {
            expect(() => assertTransition('PENDING', 'SUCCESS')).toThrow(ConflictError);
        });

        it('should reject invalid skip from PENDING to FAILED', () => {
            expect(() => assertTransition('PENDING', 'FAILED')).toThrow(ConflictError);
        });

        it('should reject transitions from terminal state SUCCESS', () => {
            expect(() => assertTransition('SUCCESS', 'PROCESSING')).toThrow(ConflictError);
            expect(() => assertTransition('SUCCESS', 'FAILED')).toThrow(ConflictError);
        });

        it('should reject transitions from terminal state FAILED', () => {
            expect(() => assertTransition('FAILED', 'PROCESSING')).toThrow(ConflictError);
            expect(() => assertTransition('FAILED', 'SUCCESS')).toThrow(ConflictError);
        });

        it('should reject self-transitions', () => {
            expect(() => assertTransition('PENDING', 'PENDING')).toThrow(ConflictError);
            expect(() => assertTransition('PROCESSING', 'PROCESSING')).toThrow(ConflictError);
        });
    });

    describe('isTerminal', () => {
        it('should identify SUCCESS and FAILED as terminal', () => {
            expect(isTerminal('SUCCESS')).toBe(true);
            expect(isTerminal('FAILED')).toBe(true);
        });

        it('should identify PENDING and PROCESSING as non-terminal', () => {
            expect(isTerminal('PENDING')).toBe(false);
            expect(isTerminal('PROCESSING')).toBe(false);
        });
    });
});

import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { JsonPaymentRepo } from '../src/repositories/jsonPaymentRepo';
import { ConflictError, NotFoundError, ValidationError } from '../src/error';

describe('JsonPaymentRepo', () => {
    let testFilePath: string;
    let repo: JsonPaymentRepo;

    beforeEach(async () => {
        const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
        testFilePath = path.join(os.tmpdir(), `payments-test-${uniqueId}.json`);
        repo = new JsonPaymentRepo(testFilePath);
        await repo.init();
    });

    afterEach(async () => {
        await fs.rm(testFilePath, { force: true }).catch(() => {});
    });

    describe('Initialization', () => {
        it('should create an empty array in storage file if it does not exist', async () => {
            const raw = await fs.readFile(testFilePath, 'utf-8');
            expect(JSON.parse(raw)).toEqual([]);
        });
    });

    describe('create()', () => {
        it('should create a payment with initial PENDING status and history', async () => {
            const result = await repo.create({
                amount: 5000,
                currency: 'NGN',
                idempotencyKey: 'idemp-1',
            });

            expect(result.created).toBe(true);
            expect(result.payment.id).toBeDefined();
            expect(result.payment.amount).toBe(5000);
            expect(result.payment.currency).toBe('NGN');
            expect(result.payment.status).toBe('PENDING');
            expect(result.payment.history).toHaveLength(1);
            expect(result.payment.history[0].status).toBe('PENDING');
            expect(result.payment.createdAt).toBeDefined();
            expect(result.payment.updatedAt).toBeDefined();

            // Verify disk persistence
            const onDisk = JSON.parse(await fs.readFile(testFilePath, 'utf-8'));
            expect(onDisk).toHaveLength(1);
            expect(onDisk[0].id).toBe(result.payment.id);
        });

        it('should return existing payment with created=false on identical idempotency key replay', async () => {
            const first = await repo.create({
                amount: 5000,
                currency: 'NGN',
                idempotencyKey: 'key-replay',
            });
            expect(first.created).toBe(true);

            const second = await repo.create({
                amount: 5000,
                currency: 'NGN',
                idempotencyKey: 'key-replay',
            });

            expect(second.created).toBe(false);
            expect(second.payment.id).toBe(first.payment.id);

            const onDisk = JSON.parse(await fs.readFile(testFilePath, 'utf-8'));
            expect(onDisk).toHaveLength(1);
        });

        it('should throw ConflictError if idempotency key is reused with different amount', async () => {
            await repo.create({
                amount: 5000,
                currency: 'NGN',
                idempotencyKey: 'conflict-amount',
            });

            await expect(
                repo.create({
                    amount: 9000,
                    currency: 'NGN',
                    idempotencyKey: 'conflict-amount',
                })
            ).rejects.toThrow(ConflictError);
        });

        it('should throw ConflictError if idempotency key is reused with different currency', async () => {
            await repo.create({
                amount: 5000,
                currency: 'NGN',
                idempotencyKey: 'conflict-currency',
            });

            await expect(
                repo.create({
                    amount: 5000,
                    currency: 'USD',
                    idempotencyKey: 'conflict-currency',
                })
            ).rejects.toThrow(ConflictError);
        });
    });

    describe('findById()', () => {
        it('should return payment by ID', async () => {
            const { payment } = await repo.create({ amount: 2000, currency: 'USD' });
            const found = await repo.findById(payment.id);
            expect(found).not.toBeNull();
            expect(found?.id).toBe(payment.id);
        });

        it('should return null for non-existent ID', async () => {
            const found = await repo.findById('non-existent-id');
            expect(found).toBeNull();
        });
    });

    describe('findByStatus()', () => {
        it('should filter payments and sort oldest first by createdAt', async () => {
            const first = await repo.create({ amount: 1000, currency: 'NGN' });
            // Small pause to guarantee different timestamps
            await new Promise(r => setTimeout(r, 10));
            const second = await repo.create({ amount: 2000, currency: 'NGN' });

            const results = await repo.findByStatus('PENDING');
            expect(results).toHaveLength(2);
            expect(results[0].id).toBe(first.payment.id);
            expect(results[1].id).toBe(second.payment.id);
            expect(new Date(results[0].createdAt).getTime()).toBeLessThanOrEqual(
                new Date(results[1].createdAt).getTime()
            );
        });
    });

    describe('update()', () => {
        it('should transition status from PENDING to PROCESSING and append history', async () => {
            const { payment } = await repo.create({ amount: 1000, currency: 'NGN' });

            const updated = await repo.update(payment.id, 'PENDING', { status: 'PROCESSING' });

            expect(updated.status).toBe('PROCESSING');
            expect(updated.history).toHaveLength(2);
            expect(updated.history[0].status).toBe('PENDING');
            expect(updated.history[1].status).toBe('PROCESSING');
        });

        it('should throw NotFoundError if payment ID is not found', async () => {
            await expect(
                repo.update('missing-id', 'PENDING', { status: 'PROCESSING' })
            ).rejects.toThrow(NotFoundError);
        });

        it('should throw ConflictError if expectedStatus does not match current status (optimistic lock)', async () => {
            const { payment } = await repo.create({ amount: 1000, currency: 'NGN' });

            await expect(
                repo.update(payment.id, 'PROCESSING', { status: 'SUCCESS' })
            ).rejects.toThrow(ConflictError);
        });

        it('should throw ConflictError on invalid state transition (PENDING -> SUCCESS)', async () => {
            const { payment } = await repo.create({ amount: 1000, currency: 'NGN' });

            await expect(
                repo.update(payment.id, 'PENDING', { status: 'SUCCESS' })
            ).rejects.toThrow(ConflictError);
        });

        it('should require failureReason when status is FAILED', async () => {
            const { payment } = await repo.create({ amount: 1000, currency: 'NGN' });
            await repo.update(payment.id, 'PENDING', { status: 'PROCESSING' });

            await expect(
                repo.update(payment.id, 'PROCESSING', { status: 'FAILED' } as any)
            ).rejects.toThrow(ValidationError);
        });

        it('should update to FAILED when valid failureReason is provided', async () => {
            const { payment } = await repo.create({ amount: 1000, currency: 'NGN' });
            await repo.update(payment.id, 'PENDING', { status: 'PROCESSING' });

            const failed = await repo.update(payment.id, 'PROCESSING', {
                status: 'FAILED',
                failureReason: 'Insufficient funds',
            });

            expect(failed.status).toBe('FAILED');
            expect(failed.failureReason).toBe('Insufficient funds');
        });

        it('should reject failureReason when status is not FAILED', async () => {
            const { payment } = await repo.create({ amount: 1000, currency: 'NGN' });

            await expect(
                repo.update(payment.id, 'PENDING', {
                    status: 'PROCESSING',
                    failureReason: 'Not allowed',
                } as any)
            ).rejects.toThrow(ValidationError);
        });
    });

    describe('Concurrency and Queueing', () => {
        it('should process concurrent writes cleanly through the PromiseQueue without file corruption', async () => {
            const writes = Array.from({ length: 10 }, (_, i) =>
                repo.create({
                    amount: 1000 + i,
                    currency: 'NGN',
                    idempotencyKey: `concurrent-${i}`,
                })
            );

            const results = await Promise.all(writes);
            expect(results).toHaveLength(10);

            const onDisk = JSON.parse(await fs.readFile(testFilePath, 'utf-8'));
            expect(onDisk).toHaveLength(10);
        });
    });
});

import request from 'supertest';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { createApp } from '../src/app';
import { JsonPaymentRepo } from '../src/repositories/jsonPaymentRepo';

describe('Payments API Endpoints', () => {
    let testFilePath: string;
    let repo: JsonPaymentRepo;
    let app: ReturnType<typeof createApp>;

    beforeEach(async () => {
        const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
        testFilePath = path.join(os.tmpdir(), `api-test-${uniqueId}.json`);
        repo = new JsonPaymentRepo(testFilePath);
        await repo.init();
        app = createApp(repo);
    });

    afterEach(async () => {
        await fs.rm(testFilePath, { force: true }).catch(() => {});
    });

    describe('GET /health', () => {
        it('should return 200 status ok and have X-Powered-By disabled', async () => {
            const res = await request(app).get('/health');

            expect(res.status).toBe(200);
            expect(res.body).toEqual({ status: 'ok' });
            expect(res.headers['x-powered-by']).toBeUndefined();
        });
    });

    describe('POST /payments', () => {
        it('should return 201 Created on new payment', async () => {
            const res = await request(app)
                .post('/payments')
                .set('Idempotency-Key', 'k1')
                .send({ amount: 5000, currency: 'ngn' });

            expect(res.status).toBe(201);
            expect(res.body.success).toBe(true);
            expect(res.body.data.id).toBeDefined();
            expect(res.body.data.amount).toBe(5000);
            expect(res.body.data.currency).toBe('NGN');
            expect(res.body.data.status).toBe('PENDING');
            expect(res.body.data.idempotencyKey).toBe('k1');
            expect(res.headers['x-powered-by']).toBeUndefined();
        });

        it('should return 200 OK on idempotent retry with the exact same key', async () => {
            // First call
            const firstRes = await request(app)
                .post('/payments')
                .set('Idempotency-Key', 'k2')
                .send({ amount: 7500, currency: 'USD' });
            expect(firstRes.status).toBe(201);

            // Replay call
            const secondRes = await request(app)
                .post('/payments')
                .set('Idempotency-Key', 'k2')
                .send({ amount: 7500, currency: 'USD' });

            expect(secondRes.status).toBe(200);
            expect(secondRes.body.success).toBe(true);
            expect(secondRes.body.data.id).toBe(firstRes.body.data.id);
        });

        it('should return 409 Conflict if same idempotency key is reused with different parameters', async () => {
            await request(app)
                .post('/payments')
                .set('Idempotency-Key', 'k3')
                .send({ amount: 3000, currency: 'EUR' });

            const conflictRes = await request(app)
                .post('/payments')
                .set('Idempotency-Key', 'k3')
                .send({ amount: 9999, currency: 'EUR' });

            expect(conflictRes.status).toBe(409);
            expect(conflictRes.body.success).toBe(false);
            expect(conflictRes.body.error.code).toBe('CONFLICT');
        });

        it('should return 400 Bad Request on decimal amount', async () => {
            const res = await request(app)
                .post('/payments')
                .send({ amount: 50.75, currency: 'NGN' });

            expect(res.status).toBe(400);
            expect(res.body.success).toBe(false);
            expect(res.body.error.code).toBe('VALIDATION_ERROR');
        });

        it('should return 400 Bad Request on negative amount', async () => {
            const res = await request(app)
                .post('/payments')
                .send({ amount: -100, currency: 'NGN' });

            expect(res.status).toBe(400);
            expect(res.body.success).toBe(false);
            expect(res.body.error.code).toBe('VALIDATION_ERROR');
        });

        it('should return 400 Bad Request on invalid currency code length', async () => {
            const res = await request(app)
                .post('/payments')
                .send({ amount: 1000, currency: 'US' });

            expect(res.status).toBe(400);
            expect(res.body.success).toBe(false);
            expect(res.body.error.code).toBe('VALIDATION_ERROR');
        });
    });

    describe('GET /payments/:id', () => {
        it('should return 200 OK and payment data for existing payment', async () => {
            const createRes = await request(app)
                .post('/payments')
                .send({ amount: 4500, currency: 'GBP' });

            const paymentId = createRes.body.data.id;

            const getRes = await request(app).get(`/payments/${paymentId}`);

            expect(getRes.status).toBe(200);
            expect(getRes.body.success).toBe(true);
            expect(getRes.body.data.id).toBe(paymentId);
            expect(getRes.body.data.amount).toBe(4500);
            expect(getRes.body.data.currency).toBe('GBP');
        });

        it('should return 404 Not Found for non-existent payment ID', async () => {
            const res = await request(app).get('/payments/non-existent-id');

            expect(res.status).toBe(404);
            expect(res.body.success).toBe(false);
            expect(res.body.error.code).toBe('NOT_FOUND');
        });
    });

    describe('404 Handling', () => {
        it('should return 404 Not Found on undefined routes', async () => {
            const res = await request(app).get('/unknown-endpoint');

            expect(res.status).toBe(404);
            expect(res.body.success).toBe(false);
            expect(res.body.error.code).toBe('NOT_FOUND');
        });
    });
});

const { createDefaultPreset } = require("ts-jest");

const tsJestTransformCfg = createDefaultPreset().transform;

/** @type {import("jest").Config} **/
module.exports = {
  testEnvironment: "node",
  watchman: false,
  transform: {
    ...tsJestTransformCfg,
  },
};

