describe('PATCH /payments/:id/status (Protected Operator Endpoint)', () => {
    describe('Authentication & Authorization', () => {
        it('should return 401 Unauthorized if admin API key header is missing', async () => {
            const createRes = await request(app)
                .post('/payments')
                .send({ amount: 1000, currency: 'USD' });

            const id = createRes.body.data.id;

            const res = await request(app)
                .patch(`/payments/${id}/status`)
                .send({ status: 'PROCESSING' });

            expect(res.status).toBe(401);
            expect(res.body.success).toBe(false);
            expect(res.body.error.code).toBe('UNAUTHORIZED');
            expect(res.body.error.message).toBe('Missing or invalid admin API key');
        });

        it('should return 401 Unauthorized if admin API key is invalid', async () => {
            const createRes = await request(app)
                .post('/payments')
                .send({ amount: 1000, currency: 'USD' });

