import { Payment } from '../domain/payment';
import { PaymentRepository } from '../domain/paymentRepository';
import { ConflictError } from '../error';

export interface BankResponse {
    success: boolean;
    error?: string;
}

export type BankProcessor = (payment: Payment, attempt: number) => Promise<BankResponse>;

export interface PaymentWorkerOptions {
    /** Interval in ms between polling ticks. Default: 1000 */
    pollIntervalMs?: number;
    /** Maximum number of payments to process concurrently. Default: 3 */
    concurrency?: number;
    /** Maximum bank call attempts before marking FAILED. Default: 3 */
    maxRetries?: number;
    /** Initial delay in ms before the first retry. Default: 100 */
    initialRetryDelayMs?: number;
    /** Backoff multiplier for successive retries. Default: 2 */
    retryBackoffFactor?: number;
    /** Simulated latency in ms for bank call. Default: 50 */
    bankLatencyMs?: number;
    /** Configure whether the bank call succeeds (boolean or function per attempt). Default: true */
    shouldBankSucceed?: boolean | ((payment: Payment, attempt: number) => boolean);
    /** Optional custom processor to override default mock bank behavior */
    bankProcessor?: BankProcessor;
}

export class PaymentWorker {
    private isRunning = false;
    private pollTimer: NodeJS.Timeout | null = null;
    private readonly activeJobs = new Set<Promise<void>>();

    private readonly pollIntervalMs: number;
    private readonly concurrency: number;
    private readonly maxRetries: number;
    private readonly initialRetryDelayMs: number;
    private readonly retryBackoffFactor: number;
    private readonly bankLatencyMs: number;
    private readonly shouldBankSucceed: boolean | ((payment: Payment, attempt: number) => boolean);
    private readonly customBankProcessor?: BankProcessor;

    constructor(
        private readonly repo: PaymentRepository,
        options: PaymentWorkerOptions = {}
    ) {
        this.pollIntervalMs = options.pollIntervalMs ?? 1000;
        this.concurrency = Math.max(1, options.concurrency ?? 3);
        this.maxRetries = Math.max(1, options.maxRetries ?? 3);
        this.initialRetryDelayMs = options.initialRetryDelayMs ?? 100;
        this.retryBackoffFactor = options.retryBackoffFactor ?? 2;
        this.bankLatencyMs = options.bankLatencyMs ?? 50;
        this.shouldBankSucceed = options.shouldBankSucceed ?? true;
        this.customBankProcessor = options.bankProcessor;
    }

    /**
     * Start the background worker. Recovers stuck payments first, then starts the poll loop.
     */
    async start(): Promise<void> {
        if (this.isRunning) return;
        this.isRunning = true;

        // Startup recovery: find payments stuck in PROCESSING from crash/restart and finish them
        await this.recoverStuckPayments();

        // Start periodic polling
        this.scheduleNextPoll(0);
    }

    /**
     * Gracefully stops the worker, waiting for in-flight payment jobs to complete.
     */
    async stop(): Promise<void> {
        this.isRunning = false;
        if (this.pollTimer) {
            clearTimeout(this.pollTimer);
            this.pollTimer = null;
        }

        // Wait for all currently executing payment jobs to finish
        await Promise.all(Array.from(this.activeJobs));
    }

    getActiveJobsCount(): number {
        return this.activeJobs.size;
    }

    getIsRunning(): boolean {
        return this.isRunning;
    }

    /**
     * Finds payments left in PROCESSING from a prior crash and completes them.
     */
    async recoverStuckPayments(): Promise<void> {
        try {
            const stuck = await this.repo.findByStatus('PROCESSING');
            for (const payment of stuck) {
                if (!this.isRunning) break;
                await this.processPaymentThroughBank(payment);
            }
        } catch (err) {
            console.error('[PaymentWorker] Failed during stuck payments recovery:', err);
        }
    }

    private scheduleNextPoll(delayMs = this.pollIntervalMs): void {
        if (!this.isRunning) return;
        this.pollTimer = setTimeout(async () => {
            await this.poll();
        }, delayMs);
    }

    private async poll(): Promise<void> {
        if (!this.isRunning) return;

        try {
            const availableSlots = this.concurrency - this.activeJobs.size;
            if (availableSlots > 0) {
                const pending = await this.repo.findByStatus('PENDING');
                const batch = pending.slice(0, availableSlots);

                for (const payment of batch) {
                    if (this.activeJobs.size >= this.concurrency) break;

                    const job = this.handlePaymentLifecycle(payment);
                    this.activeJobs.add(job);
                    job.finally(() => {
                        this.activeJobs.delete(job);
                    });
                }
            }
        } catch (err) {
            console.error('[PaymentWorker] Error during polling tick:', err);
        } finally {
            if (this.isRunning) {
                this.scheduleNextPoll();
            }
        }
    }

    private async handlePaymentLifecycle(payment: Payment): Promise<void> {
        try {
            // 1. Claim payment first with optimistic lock: PENDING -> PROCESSING
            let claimedPayment: Payment;
            try {
                claimedPayment = await this.repo.update(payment.id, 'PENDING', {
                    status: 'PROCESSING',
                });
            } catch (err) {
                if (err instanceof ConflictError) {
                    // Someone else already grabbed this payment or status changed: skip cleanly
                    return;
                }
                throw err;
            }

            // 2. Execute bank communication with retry backoff
            await this.processPaymentThroughBank(claimedPayment);
        } catch (err) {
            console.error(`[PaymentWorker] Unexpected failure processing payment ${payment.id}:`, err);
        }
    }

    private async processPaymentThroughBank(payment: Payment): Promise<void> {
        let attempt = 0;
        let lastError = 'Bank transaction failed';
        let isSuccess = false;

        while (attempt < this.maxRetries) {
            attempt++;

            try {
                const result = await this.callBank(payment, attempt);
                if (result.success) {
                    isSuccess = true;
                    break;
                }
                lastError = result.error || `Bank declined on attempt ${attempt}`;
            } catch (err: any) {
                lastError = err?.message || `Bank threw exception on attempt ${attempt}`;
            }

            if (attempt < this.maxRetries) {
                const backoffDelay = this.initialRetryDelayMs * Math.pow(this.retryBackoffFactor, attempt - 1);
                await this.sleep(backoffDelay);
            }
        }

        try {
            if (isSuccess) {
                await this.repo.update(payment.id, 'PROCESSING', {
                    status: 'SUCCESS',
                });
            } else {
                await this.repo.update(payment.id, 'PROCESSING', {
                    status: 'FAILED',
                    failureReason: `Bank failed after ${attempt} attempt(s): ${lastError}`,
                });
            }
        } catch (err) {
            if (err instanceof ConflictError) {
                console.warn(`[PaymentWorker] Terminal state conflict for ${payment.id}. Already modified.`);
                return;
            }
            console.error(`[PaymentWorker] Failed to update terminal state for ${payment.id}:`, err);
        }
    }

    private async callBank(payment: Payment, attempt: number): Promise<BankResponse> {
        if (this.customBankProcessor) {
            return this.customBankProcessor(payment, attempt);
        }

        if (this.bankLatencyMs > 0) {
            await this.sleep(this.bankLatencyMs);
        }

        const shouldSucceed = typeof this.shouldBankSucceed === 'function'
            ? this.shouldBankSucceed(payment, attempt)
            : this.shouldBankSucceed;

        if (shouldSucceed) {
            return { success: true };
        } else {
            return {
                success: false,
                error: 'Simulated bank decline: insufficient funds or communication error',
            };
        }
    }

    private sleep(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}

