import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { JsonPaymentRepo } from '../src/repositories/jsonPaymentRepo';
import { PaymentWorker } from '../src/workers/paymentWorker';

describe('PaymentWorker', () => {
    let testFilePath: string;
    let repo: JsonPaymentRepo;

    beforeEach(async () => {
        const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
        testFilePath = path.join(os.tmpdir(), `worker-test-${uniqueId}.json`);
        repo = new JsonPaymentRepo(testFilePath);
        await repo.init();
    });

    afterEach(async () => {
        await fs.rm(testFilePath, { force: true }).catch(() => {});
    });

    it('should poll for PENDING payment, mark it PROCESSING, and finish as SUCCESS', async () => {
        const { payment } = await repo.create({ amount: 2500, currency: 'USD' });
        expect(payment.status).toBe('PENDING');

        const worker = new PaymentWorker(repo, {
            pollIntervalMs: 50,
            bankLatencyMs: 10,
            shouldBankSucceed: true,
        });

        await worker.start();

        // Wait a short time for worker to process
        await new Promise(r => setTimeout(r, 200));
        await worker.stop();

        const updated = await repo.findById(payment.id);
        expect(updated).not.toBeNull();
        expect(updated?.status).toBe('SUCCESS');
        expect(updated?.history).toHaveLength(3);
        expect(updated?.history[0].status).toBe('PENDING');
        expect(updated?.history[1].status).toBe('PROCESSING');
        expect(updated?.history[2].status).toBe('SUCCESS');
    });

    it('should retry on failure with backoff and succeed if retry passes', async () => {
        const { payment } = await repo.create({ amount: 1500, currency: 'EUR' });

        let attemptsMade = 0;
        const worker = new PaymentWorker(repo, {
            pollIntervalMs: 50,
            bankLatencyMs: 5,
            maxRetries: 3,
            initialRetryDelayMs: 20,
            retryBackoffFactor: 2,
            bankProcessor: async (_payment, attempt) => {
                attemptsMade = attempt;
                if (attempt < 2) {
                    return { success: false, error: 'Temporary bank timeout' };
                }
                return { success: true };
            },
        });

        await worker.start();
        await new Promise(r => setTimeout(r, 250));
        await worker.stop();

        expect(attemptsMade).toBe(2);
        const updated = await repo.findById(payment.id);
        expect(updated?.status).toBe('SUCCESS');
    });

    it('should mark payment FAILED with reason if all retries are exhausted', async () => {
        const { payment } = await repo.create({ amount: 3000, currency: 'NGN' });

        let attemptsMade = 0;
        const worker = new PaymentWorker(repo, {
            pollIntervalMs: 50,
            bankLatencyMs: 5,
            maxRetries: 3,
            initialRetryDelayMs: 20,
            retryBackoffFactor: 1.5,
            bankProcessor: async (_payment, attempt) => {
                attemptsMade = attempt;
                return { success: false, error: 'Insufficient funds' };
            },
        });

        await worker.start();
        await new Promise(r => setTimeout(r, 300));
        await worker.stop();

        expect(attemptsMade).toBe(3);
        const updated = await repo.findById(payment.id);
        expect(updated?.status).toBe('FAILED');
        expect(updated?.failureReason).toContain('Insufficient funds');
        expect(updated?.failureReason).toContain('after 3 attempt(s)');
    });

    it('should skip payment cleanly if another worker or process already grabbed it', async () => {
        const { payment } = await repo.create({ amount: 1000, currency: 'USD' });

        // Worker 1 and Worker 2 both observe the pending payment
        // We simulate Worker 1 grabbing it before Worker 2 attempts
        await repo.update(payment.id, 'PENDING', { status: 'PROCESSING' });

        const worker = new PaymentWorker(repo, {
            pollIntervalMs: 50,
            bankLatencyMs: 5,
        });

        // Worker should not throw and safely skip
        await expect(worker['handlePaymentLifecycle'](payment)).resolves.not.toThrow();
    });

    it('should respect concurrency limits and not process more than the configured max at once', async () => {
        const payments = await Promise.all([
            repo.create({ amount: 100, currency: 'USD' }),
            repo.create({ amount: 200, currency: 'USD' }),
            repo.create({ amount: 300, currency: 'USD' }),
            repo.create({ amount: 400, currency: 'USD' }),
        ]);

        let maxConcurrentObserved = 0;
        let currentlyProcessing = 0;

        const worker = new PaymentWorker(repo, {
            pollIntervalMs: 20,
            concurrency: 2,
            bankProcessor: async () => {
                currentlyProcessing++;
                maxConcurrentObserved = Math.max(maxConcurrentObserved, currentlyProcessing);
                await new Promise(r => setTimeout(r, 60));
                currentlyProcessing--;
                return { success: true };
            },
        });

        await worker.start();
        await new Promise(r => setTimeout(r, 350));
        await worker.stop();

        expect(maxConcurrentObserved).toBeLessThanOrEqual(2);
        for (const p of payments) {
            const updated = await repo.findById(p.payment.id);
            expect(updated?.status).toBe('SUCCESS');
        }
    });

    it('should recover stuck PROCESSING payments on startup and complete them', async () => {
        // Create a payment and transition it to PROCESSING to simulate a crash mid-flight
        const { payment } = await repo.create({ amount: 5000, currency: 'GBP' });
        await repo.update(payment.id, 'PENDING', { status: 'PROCESSING' });

        const stuckBefore = await repo.findByStatus('PROCESSING');
        expect(stuckBefore).toHaveLength(1);

        const worker = new PaymentWorker(repo, {
            pollIntervalMs: 1000,
            bankLatencyMs: 10,
            shouldBankSucceed: true,
        });

        // Starting worker runs recoverStuckPayments
        await worker.start();
        await new Promise(r => setTimeout(r, 100));
        await worker.stop();

        const recovered = await repo.findById(payment.id);
        expect(recovered?.status).toBe('SUCCESS');
        expect(recovered?.history[recovered.history.length - 1].status).toBe('SUCCESS');
    });

    it('should catch errors and never let the application crash', async () => {
        const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

        const worker = new PaymentWorker(repo, {
            pollIntervalMs: 20,
            bankProcessor: async () => {
                throw new Error('Explosive bank network crash');
            },
            maxRetries: 1,
        });

        const { payment } = await repo.create({ amount: 1000, currency: 'USD' });

        await worker.start();
        await new Promise(r => setTimeout(r, 150));
        await worker.stop();

        const updated = await repo.findById(payment.id);
        expect(updated?.status).toBe('FAILED');
        expect(updated?.failureReason).toContain('Explosive bank network crash');

        errorSpy.mockRestore();
    });

    it('should wait for in-flight payments to finish before stop() resolves', async () => {
        const { payment } = await repo.create({ amount: 9999, currency: 'USD' });

        let jobCompleted = false;

        const worker = new PaymentWorker(repo, {
            pollIntervalMs: 20,
            bankProcessor: async () => {
                await new Promise(r => setTimeout(r, 80));
                jobCompleted = true;
                return { success: true };
            },
        });

        await worker.start();
        // Give it enough time to pick up the payment (mark PROCESSING)
        await new Promise(r => setTimeout(r, 40));

        // Now initiate stop while job is still running in bankProcessor
        await worker.stop();

        // When stop() resolves, the in-flight job must have fully finished
        expect(jobCompleted).toBe(true);

        const updated = await repo.findById(payment.id);
        expect(updated?.status).toBe('SUCCESS');
    });
});

import { Payment } from '../domain/payment';

export type BankErrorCode =
    | 'INSUFFICIENT_FUNDS'
    | 'CARD_EXPIRED'
    | 'CARD_BLOCKED'
    | 'FRAUD_REJECTED'
    | 'NETWORK_TIMEOUT'
    | 'GATEWAY_UNAVAILABLE'
    | 'RATE_LIMITED';

export interface BankTransactionResult {
    status: 'SUCCESS' | 'FAILED';
    transactionId?: string;
    errorCode?: BankErrorCode | string;
    failureReason?: string;
    isRetryable: boolean;
    timestamp: string;
}

export interface BankGateway {
    charge(payment: Payment, idempotencyKey: string): Promise<BankTransactionResult>;
    inquire(paymentId: string, idempotencyKey: string): Promise<BankTransactionResult | null>;
}

export interface MockBankOptions {
    /** Simulated latency in milliseconds. Default: 50 */
    latencyMs?: number;
    /** If set, forces all charge calls to this result */
    forcedResult?: 'SUCCESS' | 'TRANSIENT_FAILURE' | 'TERMINAL_FAILURE';
    /** Custom rules based on attempt count or payment */
    rule?: (payment: Payment, attempt: number) => 'SUCCESS' | 'TRANSIENT_FAILURE' | 'TERMINAL_FAILURE';
}

/**
 * Stateful MockBankGateway simulating realistic payment processing:
 * 1. Simulates latency
 * 2. Distinguishes transient (retryable) from terminal (non-retryable) errors
 * 3. Maintains an idempotent ledger for status inquiry during crash reconciliation
 */
export class MockBankGateway implements BankGateway {
    private readonly ledger = new Map<string, BankTransactionResult>();
    private latencyMs: number;
    private forcedResult?: 'SUCCESS' | 'TRANSIENT_FAILURE' | 'TERMINAL_FAILURE';
    private rule?: (payment: Payment, attempt: number) => 'SUCCESS' | 'TRANSIENT_FAILURE' | 'TERMINAL_FAILURE';

    constructor(options: MockBankOptions = {}) {
        this.latencyMs = options.latencyMs ?? 50;
        this.forcedResult = options.forcedResult;
        this.rule = options.rule;
    }

    setLatency(ms: number): void {
        this.latencyMs = ms;
    }

    setForcedResult(result?: 'SUCCESS' | 'TRANSIENT_FAILURE' | 'TERMINAL_FAILURE'): void {
        this.forcedResult = result;
    }

    setRule(rule?: (payment: Payment, attempt: number) => 'SUCCESS' | 'TRANSIENT_FAILURE' | 'TERMINAL_FAILURE'): void {
        this.rule = rule;
    }

    async charge(payment: Payment, idempotencyKey: string, attempt = 1): Promise<BankTransactionResult> {
        if (this.latencyMs > 0) {
            await new Promise(r => setTimeout(r, this.latencyMs));
        }

        // Idempotency check: if bank already captured this transaction, return recorded result
        const existing = this.ledger.get(idempotencyKey);
        if (existing) {
            return existing;
        }

        const outcome = this.determineOutcome(payment, attempt);

        if (outcome === 'SUCCESS') {
            const result: BankTransactionResult = {
                status: 'SUCCESS',
                transactionId: `txn_${Math.random().toString(36).slice(2, 10)}`,
                isRetryable: false,
                timestamp: new Date().toISOString(),
            };
            this.ledger.set(idempotencyKey, result);
            return result;
        }

        if (outcome === 'TERMINAL_FAILURE') {
            const result: BankTransactionResult = {
                status: 'FAILED',
                errorCode: 'INSUFFICIENT_FUNDS',
                failureReason: 'Terminal failure: Insufficient funds in account',
                isRetryable: false,
                timestamp: new Date().toISOString(),
            };
            // Terminal failures are finalized at the bank
            this.ledger.set(idempotencyKey, result);
            return result;
        }

        // Transient failure (network/timeout) - NOT stored as final in bank ledger so it can be retried
        return {
            status: 'FAILED',
            errorCode: 'NETWORK_TIMEOUT',
            failureReason: 'Transient network failure: Bank gateway connection reset',
            isRetryable: true,
            timestamp: new Date().toISOString(),
        };
    }

    async inquire(paymentId: string, idempotencyKey: string): Promise<BankTransactionResult | null> {
        if (this.latencyMs > 0) {
            await new Promise(r => setTimeout(r, Math.floor(this.latencyMs / 2)));
        }
        return this.ledger.get(idempotencyKey) || null;
    }

    private determineOutcome(payment: Payment, attempt: number): 'SUCCESS' | 'TRANSIENT_FAILURE' | 'TERMINAL_FAILURE' {
        if (this.rule) {
            return this.rule(payment, attempt);
        }
        if (this.forcedResult) {
            return this.forcedResult;
        }
        return 'SUCCESS';
    }
}

import { Payment } from '../domain/payment';
import { PaymentRepository } from '../domain/paymentRepository';
import { ConflictError } from '../error';
import { BankGateway, BankTransactionResult, MockBankGateway } from '../gateway/bankGateway';

export type WorkerState = 'STOPPED' | 'STARTING' | 'RUNNING' | 'DRAINING';

export interface BankResponse {
    success: boolean;
    error?: string;
    isRetryable?: boolean;
}

export type BankProcessor = (payment: Payment, attempt: number) => Promise<BankResponse>;

export interface PaymentWorkerOptions {
    /** Polling interval in milliseconds. Default: 1000 */
    pollIntervalMs?: number;
    /** Maximum number of concurrent payments being processed. Default: 3 */
    concurrency?: number;
    /** Maximum attempts before declaring terminal failure. Default: 3 */
    maxRetries?: number;
    /** Initial base delay for exponential backoff in ms. Default: 100 */
    initialRetryDelayMs?: number;
    /** Multiplier factor for backoff. Default: 2 */
    retryBackoffFactor?: number;
    /** Maximum cap for retry delay in ms. Default: 5000 */
    maxRetryDelayMs?: number;
    /** Whether to add jitter to backoff delay to prevent thundering herd. Default: true */
    enableJitter?: boolean;
    /** Age in ms after which a PROCESSING payment is considered orphaned/stuck. Default: 0 (recover all on start) */
    staleProcessingTimeoutMs?: number;
    /** Simulated latency in ms for default mock bank. Default: 50 */
    bankLatencyMs?: number;
    /** Configure whether the bank call succeeds (boolean or function per attempt). Default: true */
    shouldBankSucceed?: boolean | ((payment: Payment, attempt: number) => boolean);
    /** Pluggable bank gateway client implementing BankGateway */
    bankGateway?: BankGateway;
    /** Legacy bank processor function override for test backward compatibility */
    bankProcessor?: BankProcessor;
}

export interface WorkerTelemetryEvent {
    timestamp: string;
    workerId: string;
    type: 'CLAIM' | 'BANK_ATTEMPT' | 'RETRY' | 'SUCCESS' | 'FAILED' | 'RECONCILED' | 'SKIPPED' | 'ERROR';
    paymentId: string;
    attempt?: number;
    details?: Record<string, unknown>;
}

export class PaymentWorker {
    public readonly workerId: string;
    private state: WorkerState = 'STOPPED';
    private pollTimer: NodeJS.Timeout | null = null;
    private readonly activeJobs = new Set<Promise<void>>();
    private abortController = new AbortController();

    private readonly pollIntervalMs: number;
    private readonly concurrency: number;
    private readonly maxRetries: number;
    private readonly initialRetryDelayMs: number;
    private readonly retryBackoffFactor: number;
    private readonly maxRetryDelayMs: number;
    private readonly enableJitter: boolean;
    private readonly staleProcessingTimeoutMs: number;

    private readonly bankGateway: BankGateway;
    private readonly legacyProcessor?: BankProcessor;

    constructor(
        private readonly repo: PaymentRepository,
        options: PaymentWorkerOptions = {}
    ) {
        this.workerId = `worker_${Math.random().toString(36).slice(2, 8)}`;
        this.pollIntervalMs = Math.max(10, options.pollIntervalMs ?? 1000);
        this.concurrency = Math.max(1, options.concurrency ?? 3);
        this.maxRetries = Math.max(1, options.maxRetries ?? 3);
        this.initialRetryDelayMs = Math.max(1, options.initialRetryDelayMs ?? 100);
        this.retryBackoffFactor = Math.max(1, options.retryBackoffFactor ?? 2);
        this.maxRetryDelayMs = options.maxRetryDelayMs ?? 5000;
        this.enableJitter = options.enableJitter ?? true;
        this.staleProcessingTimeoutMs = options.staleProcessingTimeoutMs ?? 0;

        this.legacyProcessor = options.bankProcessor;

        if (options.bankGateway) {
            this.bankGateway = options.bankGateway;
        } else {
            const shouldSucceed = options.shouldBankSucceed ?? true;
            this.bankGateway = new MockBankGateway({
                latencyMs: options.bankLatencyMs ?? 50,
                rule: (payment, attempt) => {
                    const ok = typeof shouldSucceed === 'function'
                        ? shouldSucceed(payment, attempt)
                        : shouldSucceed;
                    return ok ? 'SUCCESS' : 'TRANSIENT_FAILURE';
                },
            });
        }
    }

    getState(): WorkerState {
        return this.state;
    }

    getIsRunning(): boolean {
        return this.state === 'RUNNING';
    }

    getActiveJobsCount(): number {
        return this.activeJobs.size;
    }

    /**
     * Start the worker.
     * 1. Reconciles any orphaned payments left in PROCESSING from an earlier crash.
     * 2. Starts periodic polling loop for new PENDING transactions.
     */
    async start(): Promise<void> {
        if (this.state === 'RUNNING' || this.state === 'STARTING') return;

        this.state = 'STARTING';
        this.abortController = new AbortController();

        // Phase 1: Reconcile stuck/orphaned payments from a prior crash
        await this.recoverStuckPayments();

        if (this.state === 'STARTING') {
            this.state = 'RUNNING';
            this.scheduleNextPoll(0);
        }
    }

    /**
     * Gracefully stops the worker:
     * 1. Stops polling.
     * 2. Signals abort for any active sleep timers.
     * 3. Awaits all currently executing payment processing jobs to complete.
     */
    async stop(): Promise<void> {
        if (this.state === 'STOPPED') return;

        this.state = 'DRAINING';

        if (this.pollTimer) {
            clearTimeout(this.pollTimer);
            this.pollTimer = null;
        }

        // Abort pending backoff sleep timers
        this.abortController.abort();

        // Await all in-flight jobs to finish cleanly
        await Promise.all(Array.from(this.activeJobs));

        this.state = 'STOPPED';
    }

    /**
     * Startup reconciliation:
     * Discovers payments stranded in PROCESSING from a sudden crash/restart.
     * Uses Two-Phase Recovery:
     *   1. Queries the bank first using the payment's idempotency key.
     *   2. If the bank already captured it, updates locally to SUCCESS (prevents duplicate charges).
     *   3. If not yet captured, resumes normal processing.
     */
    async recoverStuckPayments(): Promise<void> {
        try {
            const stuckPayments = await this.repo.findByStatus('PROCESSING');
            const now = Date.now();

            const eligiblePayments = stuckPayments.filter(p => {
                if (this.staleProcessingTimeoutMs <= 0) return true;
                const updatedTime = new Date(p.updatedAt).getTime();
                return now - updatedTime >= this.staleProcessingTimeoutMs;
            });

            if (eligiblePayments.length > 0) {
                this.log({
                    type: 'RECONCILED',
                    paymentId: 'BATCH',
                    details: { count: eligiblePayments.length },
                });
            }

            for (const payment of eligiblePayments) {
                if (this.state === 'STOPPED' || this.state === 'DRAINING') break;

                const idempotencyKey = payment.idempotencyKey || `idem_${payment.id}`;

                // Phase 1: Bank Inquiry (Did the bank process this before the crash?)
                let priorResult: BankTransactionResult | null = null;
                try {
                    priorResult = await this.bankGateway.inquire(payment.id, idempotencyKey);
                } catch (inquireErr) {
                    console.warn(`[PaymentWorker] Status inquiry failed for stuck payment ${payment.id}:`, inquireErr);
                }

                if (priorResult && priorResult.status === 'SUCCESS') {
                    // Bank already processed it: finalize locally without double-charging
                    await this.updateTerminalState(payment.id, 'SUCCESS');
                    continue;
                }

                if (priorResult && priorResult.status === 'FAILED' && !priorResult.isRetryable) {
                    // Bank already rejected it: finalize locally
                    await this.updateTerminalState(
                        payment.id,
                        'FAILED',
                        priorResult.failureReason || 'Declined prior to crash'
                    );
                    continue;
                }

                // Phase 2: Not yet captured or transient — finish processing through bank
                await this.executeBankFlow(payment);
            }
        } catch (err) {
            console.error('[PaymentWorker] Failed during stuck payments recovery:', err);
        }
    }

    private scheduleNextPoll(delayMs = this.pollIntervalMs): void {
        if (this.state !== 'RUNNING') return;

        this.pollTimer = setTimeout(async () => {
            await this.poll();
        }, delayMs);
    }

    private async poll(): Promise<void> {
        if (this.state !== 'RUNNING') return;

        try {
            // Check concurrency slots before hitting database
            const availableSlots = this.concurrency - this.activeJobs.size;
            if (availableSlots > 0) {
                const pending = await this.repo.findByStatus('PENDING');
                const batch = pending.slice(0, availableSlots);

                for (const payment of batch) {
                    if (this.activeJobs.size >= this.concurrency || this.state !== 'RUNNING') {
                        break;
                    }

                    const jobPromise = this.processPayment(payment);
                    this.activeJobs.add(jobPromise);
                    jobPromise.finally(() => {
                        this.activeJobs.delete(jobPromise);
                    });
                }
            }
        } catch (err) {
            console.error('[PaymentWorker] Error in polling loop:', err);
        } finally {
            if (this.state === 'RUNNING') {
                this.scheduleNextPoll();
            }
        }
    }

    private async processPayment(payment: Payment): Promise<void> {
        try {
            // Step 1: Claim payment atomically (PENDING -> PROCESSING)
            let claimedPayment: Payment;
            try {
                claimedPayment = await this.repo.update(payment.id, 'PENDING', {
                    status: 'PROCESSING',
                });
                this.log({ type: 'CLAIM', paymentId: payment.id });
            } catch (err) {
                if (err instanceof ConflictError) {
                    // Contention: another worker or admin already modified this payment
                    this.log({
                        type: 'SKIPPED',
                        paymentId: payment.id,
                        details: { reason: 'Optimistic lock contention' },
                    });
                    return;
                }
                throw err;
            }

            // Step 2: Execute bank interaction with retry policy
            await this.executeBankFlow(claimedPayment);
        } catch (err) {
            console.error(`[PaymentWorker] Uncaught exception processing payment ${payment.id}:`, err);
        }
    }

    private async executeBankFlow(payment: Payment): Promise<void> {
        const idempotencyKey = payment.idempotencyKey || `idem_${payment.id}`;
        let attempt = 0;
        let lastError = 'Bank transaction failed';
        let isSuccess = false;

        while (attempt < this.maxRetries) {
            attempt++;
            this.log({ type: 'BANK_ATTEMPT', paymentId: payment.id, attempt });

            let attemptResult: { success: boolean; error?: string; isRetryable?: boolean };

            try {
                if (this.legacyProcessor) {
                    // Legacy processor support
                    const resp = await this.legacyProcessor(payment, attempt);
                    attemptResult = {
                        success: resp.success,
                        error: resp.error,
                        isRetryable: resp.isRetryable ?? !resp.success,
                    };
                } else {
                    const result = await this.bankGateway.charge(payment, idempotencyKey);
                    attemptResult = {
                        success: result.status === 'SUCCESS',
                        error: result.failureReason || result.errorCode,
                        isRetryable: result.isRetryable,
                    };
                }

                if (attemptResult.success) {
                    isSuccess = true;
                    break;
                }

                lastError = attemptResult.error || `Bank declined on attempt ${attempt}`;

                // Non-retryable / terminal error: do not waste retries (e.g. Insufficient funds, invalid card)
                if (attemptResult.isRetryable === false) {
                    this.log({
                        type: 'FAILED',
                        paymentId: payment.id,
                        attempt,
                        details: { reason: lastError, isTerminal: true },
                    });
                    break;
                }
            } catch (err: any) {
                lastError = err?.message || `Bank communication threw exception on attempt ${attempt}`;
            }

            if (attempt < this.maxRetries) {
                const backoffDelay = this.calculateBackoff(attempt);
                this.log({
                    type: 'RETRY',
                    paymentId: payment.id,
                    attempt,
                    details: { nextAttemptInMs: backoffDelay, error: lastError },
                });
                await this.sleep(backoffDelay);
            }
        }

        // Step 3: Transition to terminal state (SUCCESS or FAILED)
        if (isSuccess) {
            await this.updateTerminalState(payment.id, 'SUCCESS');
            this.log({ type: 'SUCCESS', paymentId: payment.id, attempt });
        } else {
            const reason = `Bank failed after ${attempt} attempt(s): ${lastError}`;
            await this.updateTerminalState(payment.id, 'FAILED', reason);
            this.log({ type: 'FAILED', paymentId: payment.id, attempt, details: { reason } });
        }
    }

    private async updateTerminalState(
        id: string,
        status: 'SUCCESS' | 'FAILED',
        failureReason?: string
    ): Promise<void> {
        try {
            if (status === 'SUCCESS') {
                await this.repo.update(id, 'PROCESSING', { status: 'SUCCESS' });
            } else {
                await this.repo.update(id, 'PROCESSING', {
                    status: 'FAILED',
                    failureReason: failureReason || 'Payment failed',
                });
            }
        } catch (err) {
            if (err instanceof ConflictError) {
                console.warn(`[PaymentWorker] Terminal state conflict for ${id}: payment status already modified.`);
                return;
            }
            console.error(`[PaymentWorker] Failed to update terminal state for ${id}:`, err);
        }
    }

    /**
     * Exponential Backoff with Full Jitter:
     * Full Jitter randomizes delay uniformly between 0 and min(maxDelay, baseDelay * 2^(attempt-1)).
     * Prevents thundering-herd effect when multiple retries coordinate on a recovered downstream service.
     */
    private calculateBackoff(attempt: number): number {
        const rawDelay = this.initialRetryDelayMs * Math.pow(this.retryBackoffFactor, attempt - 1);
        const cappedDelay = Math.min(this.maxRetryDelayMs, rawDelay);

        if (!this.enableJitter) {
            return Math.floor(cappedDelay);
        }

        return Math.floor(Math.random() * cappedDelay);
    }

    private sleep(ms: number): Promise<void> {
        if (ms <= 0) return Promise.resolve();

        return new Promise(resolve => {
            const timer = setTimeout(resolve, ms);

            // Cancel sleep immediately if worker is stopped/drained
            const onAbort = () => {
                clearTimeout(timer);
                resolve();
            };

            this.abortController.signal.addEventListener('abort', onAbort, { once: true });
        });
    }

    private log(event: Omit<WorkerTelemetryEvent, 'timestamp' | 'workerId'>): void {
        const telemetry: WorkerTelemetryEvent = {
            timestamp: new Date().toISOString(),
            workerId: this.workerId,
            ...event,
        };
        // Can be routed to Datadog/CloudWatch/Winston; output clean structured logs
        if (process.env.DEBUG_WORKER) {
            console.log(`[PaymentWorker][${telemetry.type}] ${telemetry.paymentId}:`, telemetry);
        }
    }
}

