    expect(sleepSpy).toHaveBeenNthCalledWith(2, 40); // 20 * 2^1

    // 3. Payment successfully updated to terminal SUCCESS
    const updated = await repo.findById(payment.id);
    expect(updated?.status).toBe('SUCCESS');
});

